def is_sorted(lst):
    # Check if the list is sorted in ascending order
    for i in range(len(lst) - 1):
        if lst[i] > lst[i + 1]:
            return False
    # Check for consecutive duplicates (more than two occurrences)
    if len(lst) <= 1:
        return True
    prev = lst[0]
    count = 1
    for i in range(1, len(lst)):
        if lst[i] == prev:
            count += 1
            if count > 2:
                return False
        else:
            prev = lst[i]
            count = 1
    return True
