def count_nums(arr):
    count = 0
    for num in arr:
        if num == 0:
            continue
        sign = -1 if num < 0 else 1
        abs_num = abs(num)
        digits = [int(d) for d in str(abs_num)]
        if sign == -1:
            digits[0] *= -1
        total = sum(digits)
        if total > 0:
            count += 1
    return count
