from collections import Counter

def count_reverse_pairs(lst):
    count = Counter(lst)
    total = 0
    for s in count:
        rev_s = s[::-1]
        if rev_s in count:
            if s != rev_s:
                if s < rev_s:
                    total += count[s] * count[rev_s]
    return total
